 useEffect(()=>{let active=true;loadDashboardData(API).then(({campaigns:c,leads:l,sources:s,summary:m,opportunities:o})=>{if(active){setCampaigns(c);setLeads(l);setSources(s);setSummary(m);setOpportunities(o);setApiState("API CONNECTED")}}).catch(error=>{if(active){setApiState("API OFFLINE");setApiError(error instanceof Error?error.message:"Could not connect to the Arletion API.")}});return()=>{active=false}},[reloadKey]);
 useEffect(()=>{if(page!=="Consumer enquiries"||apiState!=="API CONNECTED")return;let active=true;loadConsumerStatus(API).then(status=>{if(!active)return;setConsumerStatus(status);if(!status.enabled){setConsumerItems([]);setConsumerTotal(0);return}return loadConsumerPage(API,{category:consumerCategory==="all"?undefined:consumerCategory,status:consumerState==="all"?undefined:consumerState,province:consumerProvince.trim()||undefined,page:1,page_size:25}).then(result=>{if(active){setConsumerItems(result.items);setConsumerTotal(result.total)}})}).catch(error=>{if(active)setConsumerError(error instanceof Error?error.message:"Consumer enquiry pipeline is unavailable.")});return()=>{active=false}},[page,apiState,consumerCategory,consumerState,consumerProvince,reloadKey]);
 useEffect(()=>{if(page!=="Business leads"||apiState!=="API CONNECTED")return;let active=true;loadLeadPage(API,{q:query.trim()||undefined,lead_type:type==="all"?undefined:type,category:category==="all"?undefined:category,status:leadStatus==="all"?undefined:leadStatus,province:province.trim()||undefined,verification_status:verificationFilter==="all"?undefined:verificationFilter,page:leadPageNumber,page_size:25}).then(result=>{if(active){setLeadSearchError("");setLeads(result.items);setLeadCategories(result.categories);setLeadTotal(result.total)}}).catch(error=>{if(active)setLeadSearchError(error instanceof Error?error.message:"Lead search failed.")}).finally(()=>{if(active)setLeadLoading(false)});return()=>{active=false}},[page,apiState,query,type,category,leadStatus,province,verificationFilter,leadPageNumber,reloadKey]);
 async function approveSource(source:Source){if(!window.confirm(`Confirm you reviewed the current access, licence, and reuse terms for “${source.name}” and that this collection method is permitted.`))return;setSourceError("");setSourceBusy(source.id);try{const response=await fetch(`${API}/api/v1/sources`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:source.name,url:source.url,category:source.category,status:"enabled",note:"Approved by workspace operator after manual source-terms review."})});const payload=await response.json().catch(()=>({detail:"The API returned an unreadable response."})) as {detail?:unknown};if(!response.ok)throw new Error(typeof payload.detail==="string"?payload.detail:`Approval failed with HTTP ${response.status}.`);setReloadKey(value=>value+1)}catch(error){setSourceError(error instanceof Error?error.message:"Could not update the source registry.")}finally{setSourceBusy("")}}
 async function importOfficialBatch(){setImportError("");setImportResult(null);if(!dateFrom||!dateTo||dateFrom>dateTo){setImportError("Choose a valid date range before importing.");return}setImporting(true);try{const result=await importOfficialOpportunityPages(API,{start_page:treasuryStartPage,page_size:100,page_count:treasuryPageCount,date_from:dateFrom,date_to:dateTo});setImportResult(result);setTreasuryStartPage(result.next_page);setReloadKey(value=>value+1)}catch(error){setImportError(error instanceof Error?error.message:"The official eTender import failed.")}finally{setImporting(false)}}
 async function importFreeSupplierBatch(){setFreeSupplierError("");setFreeSupplierResult(null);if(!officialSourceEnabled){setFreeSupplierError("Approve the National Treasury eTender source in Source Registry first.");return}if(!dateFrom||!dateTo||dateFrom>dateTo){setFreeSupplierError("Choose a valid date range before importing.");return}setFreeSupplierImporting(true);try{let campaign=campaigns.find(item=>item.pipeline==="business_procurement"&&item.lead_type==="procurement");if(!campaign){campaign=await createCampaign(API,{name:"National Treasury Awarded Suppliers",objective:"Review companies named in published National Treasury award records; check current CSD status before any contact.",lead_type:"procurement",geography:"South Africa",status:"draft",criteria:{source:"National Treasury OCDS",verification:"source_confirmed"}});setCampaigns(items=>[campaign!,...items])}const result=await importFreeAwardedSupplierLeads(API,{campaign_id:campaign.id,start_page:treasuryStartPage,page_count:treasuryPageCount,date_from:dateFrom,date_to:dateTo,max_releases:2000});setFreeSupplierResult(result);setTreasuryStartPage(result.batch.next_page);setType("procurement");setCategory("all");setLeadStatus("all");setVerificationFilter("source_confirmed");setProvince("");setQuery("");setLeadPageNumber(1);const leads=await loadLeadPage(API,{lead_type:"procurement",verification_status:"source_confirmed",page:1,page_size:25});setLeads(leads.items);setLeadCategories(leads.categories);setLeadTotal(leads.total);setPage("Business leads");setReloadKey(value=>value+1)}catch(error){setFreeSupplierError(error instanceof Error?error.message:"Free Treasury supplier import failed.")}finally{setFreeSupplierImporting(false)}}
 async function recordManualVerification(lead:Lead){const registry=window.prompt("Official register checked? Enter CSD or CIPC.","CSD")?.trim().toUpperCase();if(registry!=="CSD"&&registry!=="CIPC")return;const result=window.prompt("Check result: verified, not_found, inactive, restricted or unknown.","verified")?.trim().toLowerCase();if(!["verified","not_found","inactive","restricted","unknown"].includes(result||""))return;const evidence_url=window.prompt("Paste the official CSD/CIPC evidence URL.");if(!evidence_url)return;const reference=window.prompt("Supplier/CIPC reference shown by the register.");if(!reference)return;const note=window.prompt("Optional verification notes.","")||"";setLeadCreateMessage("");try{const saved=await recordLeadVerification(API,lead.id,{registry,result:result as "verified"|"not_found"|"inactive"|"restricted"|"unknown",evidence_url,reference,note,checked_at:new Date().toISOString()});setLeadCreateMessage(saved.verification_status==="officially_verified"?`${lead.organization}: official ${registry} verification recorded.`:`${lead.organization}: ${registry} check recorded as needs review.`);setReloadKey(value=>value+1)}catch(error){setLeadCreateMessage(error instanceof Error?error.message:"Verification record failed.")}}
 async function importNCRPartners(){setNcrImportError("");setNcrImportResult(null);if(!ncrSourceEnabled){setNcrImportError("Approve the official NCR debt counsellor register in Source Registry first.");return}if(!ncrCampaignId){setNcrImportError("Create or select a Partnership campaign first.");return}setNcrImporting(true);try{const result=await importNCRDebtCounsellors(API,{campaign_id:ncrCampaignId,keyword:ncrKeyword.trim(),page:Number(ncrPage)||1,limit:100});setNcrImportResult(result);setType("partnership");setCategory("Debt counselling partners");setVerificationFilter("source_confirmed");setLeadStatus("all");setProvince("");setQuery("");setLeadPageNumber(1);setReloadKey(value=>value+1)}catch(error){setNcrImportError(error instanceof Error?error.message:"NCR directory import failed.")}finally{setNcrImporting(false)}}
